import { useState, type FormEvent } from "react";
import { useNavigate } from "react-router-dom";
import { login, logVisit } from "../api";

// Customer login: email = username, access code = password.
// The code was generated by Don for this email only. Failures show the
// generic message — they never say whether the account was terminated.

export default function Login({ onLogin }: { onLogin: () => void }) {
  const [slug, setSlug] = useState("");
  const [email, setEmail] = useState("");
  const [code, setCode] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const navigate = useNavigate();

  async function submit(e: FormEvent) {
    e.preventDefault();
    setError(""); setBusy(true);
    try {
      await logVisit(slug.trim(), false, "/");
      const data = await login(slug.trim(), email.trim(), code.trim());
      await logVisit(slug.trim(), true, "/");
      onLogin();
      navigate(`/portal/${data.portal.slug}`);
    } catch {
      setError("Invalid credentials. If you believe this is a mistake, contact the portal owner.");
    } finally { setBusy(false); }
  }

  const input = { display: "block", width: "100%", padding: 10, margin: "6px 0 12px", fontSize: 16 } as const;
  return (
    <form onSubmit={submit}>
      <h2>Sign in to your portal</h2>
      <p>Use the email Don invited and the code he gave you.</p>
      <label>Portal
        <input style={input} value={slug} onChange={(e) => setSlug(e.target.value)} placeholder="vip-coaching" required />
      </label>
      <label>Email (username)
        <input style={input} type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />
      </label>
      <label>Access code (password)
        <input style={input} value={code} onChange={(e) => setCode(e.target.value)} placeholder="XXXX-XXXX-XXXX" autoComplete="off" required />
      </label>
      {error && <p style={{ color: "red" }}>{error}</p>}
      <button type="submit" disabled={busy}>{busy ? "Signing in…" : "Sign in"}</button>
    </form>
  );
}
